import{_ as t,c as o,o as i,ae as n}from"./chunks/framework.DMK_uHmU.js";const d=JSON.parse('{"title":"Chat Token Counter User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Assistant/chat-token-counts.md","filePath":"Assistant/chat-token-counts.md"}'),a={name:"Assistant/chat-token-counts.md"};function s(l,e,r,u,c,h){return i(),o("div",null,e[0]||(e[0]=[n('<h1 id="chat-token-counter-user-guide" tabindex="-1">Chat Token Counter User Guide <a class="header-anchor" href="#chat-token-counter-user-guide" aria-label="Permalink to &quot;Chat Token Counter User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#chat-token-counter-user-guide">Chat Token Counter User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-token-counts">Accessing Token Counts</a></li><li><a href="#token-counter-interface">Token Counter Interface</a></li><li><a href="#understanding-token-metrics">Understanding Token Metrics</a><ul><li><a href="#total-requests">Total Requests</a></li><li><a href="#total-tokens">Total Tokens</a></li><li><a href="#input-tokens">Input Tokens</a></li><li><a href="#output-tokens">Output Tokens</a></li></ul></li><li><a href="#token-formatting">Token Formatting</a></li><li><a href="#empty-states">Empty States</a></li><li><a href="#loading-states">Loading States</a></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Chat Token Counter provides insights into the resource usage of your AI conversations. This component displays metrics about the number of tokens used in your interactions, helping you understand the computational resources consumed during your conversations. Tokens are the basic units that AI models process - each word is typically broken into multiple tokens, and token counts directly relate to processing cost and response time.</p><h2 id="accessing-token-counts" tabindex="-1">Accessing Token Counts <a class="header-anchor" href="#accessing-token-counts" aria-label="Permalink to &quot;Accessing Token Counts&quot;">​</a></h2><p>The Token Counter is accessible from the chat history panel:</p><ol><li>Open the Chat History sidebar in the AI Assistant</li><li>Click the three-dot menu next to a conversation</li><li>Select &quot;Token Count&quot; from the menu</li><li>The Token Counter dialog appears, showing metrics for that conversation</li></ol><h2 id="token-counter-interface" tabindex="-1">Token Counter Interface <a class="header-anchor" href="#token-counter-interface" aria-label="Permalink to &quot;Token Counter Interface&quot;">​</a></h2><p>The Token Counter displays information in a clean, card-based layout:</p><ol><li><strong>Header</strong>: &quot;Token Counts&quot; title at the top of the dialog</li><li><strong>Metric Cards</strong>: Four visual cards showing different token metrics</li><li><strong>Icons</strong>: Visual indicators for each metric type</li><li><strong>Values</strong>: Numerical displays of token counts, formatted for readability</li><li><strong>Labels</strong>: Descriptive text below each card explaining the metric</li></ol><p>Each metric card uses a consistent design with:</p><ul><li>Light blue background</li><li>Icon representing the metric type</li><li>Large numerical display</li><li>Descriptive label underneath</li></ul><h2 id="understanding-token-metrics" tabindex="-1">Understanding Token Metrics <a class="header-anchor" href="#understanding-token-metrics" aria-label="Permalink to &quot;Understanding Token Metrics&quot;">​</a></h2><h3 id="total-requests" tabindex="-1">Total Requests <a class="header-anchor" href="#total-requests" aria-label="Permalink to &quot;Total Requests&quot;">​</a></h3><p>The Requests card displays:</p><ol><li>Comment bubble icon (pi-comments)</li><li>The total number of interactions/questions in the conversation</li><li>Label &quot;Requests&quot; below the value</li><li>Each request typically consists of your question and the AI&#39;s response</li></ol><p>This metric helps you understand how many back-and-forth exchanges occurred in the conversation.</p><h3 id="total-tokens" tabindex="-1">Total Tokens <a class="header-anchor" href="#total-tokens" aria-label="Permalink to &quot;Total Tokens&quot;">​</a></h3><p>The Total Tokens card displays:</p><ol><li>Sparkle icon (pi-sparkles)</li><li>The sum of all tokens used in the conversation (input + output)</li><li>Label &quot;Total Tokens&quot; below the value</li><li>Represents the total computational resources used</li></ol><p>This is the most important metric for understanding overall resource usage of the conversation.</p><h3 id="input-tokens" tabindex="-1">Input Tokens <a class="header-anchor" href="#input-tokens" aria-label="Permalink to &quot;Input Tokens&quot;">​</a></h3><p>The Input Tokens card displays:</p><ol><li>Minimize window icon (pi-window-minimize)</li><li>The number of tokens used in your questions and prompts</li><li>Label &quot;Input Tokens&quot; below the value</li><li>Represents how much information you&#39;ve provided to the AI</li></ol><p>Input tokens include your questions, any document context provided, system instructions, and conversation history.</p><h3 id="output-tokens" tabindex="-1">Output Tokens <a class="header-anchor" href="#output-tokens" aria-label="Permalink to &quot;Output Tokens&quot;">​</a></h3><p>The Output Tokens card displays:</p><ol><li>Maximize window icon (pi-window-maximize)</li><li>The number of tokens generated in AI responses</li><li>Label &quot;Output Tokens&quot; below the value</li><li>Represents how much information the AI has generated</li></ol><p>Output tokens typically cost more computationally than input tokens and represent the AI&#39;s work in generating responses.</p><h2 id="token-formatting" tabindex="-1">Token Formatting <a class="header-anchor" href="#token-formatting" aria-label="Permalink to &quot;Token Formatting&quot;">​</a></h2><p>Large token numbers are automatically formatted for readability:</p><ol><li><p>Numbers under 1,000 display as exact values</p><ul><li>Example: 750 appears as &quot;750&quot;</li></ul></li><li><p>Numbers between 1,000 and 999,999 display with &quot;K&quot; suffix</p><ul><li>Example: 5,400 appears as &quot;5.4 K&quot;</li></ul></li><li><p>Numbers between 1,000,000 and 999,999,999 display with &quot;M&quot; suffix</p><ul><li>Example: 2,500,000 appears as &quot;2.5 M&quot;</li></ul></li><li><p>Numbers over 1 billion display with &quot;B&quot; suffix</p><ul><li>Example: 1,200,000,000 appears as &quot;1.2 B&quot;</li></ul></li><li><p>Extremely large numbers (over 1 trillion) display with &quot;T&quot; suffix</p><ul><li>Example: 1,500,000,000,000 appears as &quot;1.5 T&quot;</li></ul></li></ol><p>This makes large numbers easier to read at a glance while maintaining a clean interface.</p><h2 id="empty-states" tabindex="-1">Empty States <a class="header-anchor" href="#empty-states" aria-label="Permalink to &quot;Empty States&quot;">​</a></h2><p>If a conversation has no token data:</p><ol><li>The metric cards do not display</li><li>Instead, a light blue message box appears</li><li>Text states &quot;There are no tokens counts for this session&quot;</li><li>This typically indicates a new or unused conversation</li></ol><p>This empty state helps you understand when token data is unavailable rather than simply showing zeros.</p><h2 id="loading-states" tabindex="-1">Loading States <a class="header-anchor" href="#loading-states" aria-label="Permalink to &quot;Loading States&quot;">​</a></h2><p>While token data is being retrieved:</p><ol><li>A loading spinner appears in the center of the dialog</li><li>The spinner uses the primary theme color</li><li>The animation indicates that data is being fetched</li><li>Once data loads, the spinner disappears and metrics display</li></ol><p>The loading state provides visual feedback during data retrieval, especially important for conversations with extensive history.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effectively using the Token Counter:</p><ol><li><p><strong>Regular Monitoring</strong>:</p><ul><li>Check token usage for long conversations</li><li>Monitor trends in your token consumption</li><li>Identify unusually token-heavy conversations</li></ul></li><li><p><strong>Optimizing Conversations</strong>:</p><ul><li>Keep questions concise to reduce input tokens</li><li>Ask for more specific responses when possible</li><li>Begin new conversations for new topics rather than continuing very long ones</li></ul></li><li><p><strong>Resource Planning</strong>:</p><ul><li>Use token metrics to estimate AI usage costs</li><li>Plan for resource allocation based on conversation patterns</li><li>Identify opportunities to optimize token usage</li></ul></li><li><p><strong>Troubleshooting</strong>:</p><ul><li>Check token counts when responses seem slow</li><li>Very high token counts may indicate inefficient conversations</li><li>Abnormally low counts might suggest incomplete responses</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Token counts not loading</p><ul><li>Wait a few moments as data retrieves</li><li>Check for error messages in the interface</li><li>Try reopening the token counter dialog</li><li>Verify network connectivity</li></ul><p><strong>Issue</strong>: Unexpected zero counts</p><ul><li>New conversations may not have metrics yet</li><li>Ensure the conversation has completed requests</li><li>Check if the conversation was recently cleared</li><li>Try refreshing the token counter</li></ul><p><strong>Issue</strong>: Token counts seem unusually high</p><ul><li>Long conversations accumulate many tokens</li><li>Document attachments significantly increase token count</li><li>Complex queries with extensive context use more tokens</li><li>Consider starting a new conversation if counts are very high</li></ul><p><strong>Issue</strong>: Error messages when loading tokens</p><ul><li>Note any specific error messages displayed</li><li>Service unavailability may be temporary</li><li>Try again later if system errors appear</li><li>If persistent, contact your administrator</li></ul><p><strong>Issue</strong>: Token counts don&#39;t match conversation length</p><ul><li>Remember that tokens are not equivalent to words (usually more tokens than words)</li><li>Hidden context and system instructions also consume tokens</li><li>Document processing adds significant token usage</li><li>Each AI model tokenizes text differently</li></ul><hr><p>For additional assistance with token counter information, please contact your system administrator or refer to the platform documentation.</p>',58)]))}const m=t(a,[["render",s]]);export{d as __pageData,m as default};
